const question = (difficulty, en, hi, optionsEn, optionsHi, answer, explanationEn, explanationHi) => ({
  difficulty,
  question: { en, hi },
  options: { en: optionsEn, hi: optionsHi },
  answer,
  explanation: { en: explanationEn, hi: explanationHi },
});

const category = (id, nameEn, nameHi, questions) => ({
  id,
  name: { en: nameEn, hi: nameHi },
  questions: questions.map((item, index) => ({ ...item, id: `${id}-${index + 1}` })),
});

const assessmentCategories = [
  category("phishing", "Phishing", "फ़िशिंग", [
    question("Easy", "An email says your bank account will be blocked unless you verify it through a link. What should you do?", "एक ईमेल कहता है कि लिंक से पुष्टि न करने पर आपका बैंक खाता बंद हो जाएगा। आपको क्या करना चाहिए?", ["Click the link immediately", "Reply with your account details", "Open the bank's official app or type its address yourself", "Forward the email to friends"], ["तुरंत लिंक खोलें", "खाते की जानकारी देकर जवाब दें", "बैंक का आधिकारिक ऐप खोलें या पता स्वयं टाइप करें", "ईमेल दोस्तों को भेजें"], 2, "Urgent messages and unexpected links are common phishing tactics. Verify through a trusted channel.", "जल्दबाजी कराने वाले संदेश और अनजान लिंक फ़िशिंग के आम तरीके हैं। विश्वसनीय माध्यम से पुष्टि करें।"),
    question("Easy", "A delivery text asks for a small fee through a shortened link. What is safest?", "डिलीवरी का एक संदेश छोटे लिंक से थोड़ी फीस मांगता है। सबसे सुरक्षित तरीका क्या है?", ["Pay through the link", "Check the delivery company's official app or website", "Send your card number by text", "Ask the sender for an OTP"], ["लिंक से भुगतान करें", "डिलीवरी कंपनी के आधिकारिक ऐप या वेबसाइट पर जांचें", "कार्ड नंबर संदेश में भेजें", "भेजने वाले से OTP मांगें"], 1, "Use the official delivery service to check a parcel; don't trust unsolicited payment links.", "पार्सल जांचने के लिए आधिकारिक डिलीवरी सेवा का उपयोग करें; अनचाहे भुगतान लिंक पर भरोसा न करें।"),
    question("Easy", "A message claims you won a prize but asks you to pay a processing fee first. What should you do?", "एक संदेश कहता है कि आपने इनाम जीता है, लेकिन पहले प्रोसेसिंग फीस मांगता है। क्या करें?", ["Pay the fee to claim it", "Share your bank OTP", "Ignore it and verify any contest through its official source", "Send identity documents"], ["इनाम पाने के लिए फीस दें", "बैंक OTP साझा करें", "इसे अनदेखा करें और प्रतियोगिता की आधिकारिक स्रोत से पुष्टि करें", "पहचान के दस्तावेज भेजें"], 2, "Unexpected prizes that require upfront payment are a common scam warning sign.", "अनपेक्षित इनाम के लिए पहले भुगतान मांगना धोखाधड़ी का आम संकेत है।"),
    question("Medium", "The sender address looks almost like your employer's but has one extra character. What should you do?", "भेजने वाले का पता आपके नियोक्ता जैसा है, लेकिन उसमें एक अतिरिक्त अक्षर है। क्या करें?", ["Open the attachment because the name looks familiar", "Check the exact address and confirm through a known work channel", "Reply with your password", "Forward it to all coworkers"], ["अटैचमेंट खोलें क्योंकि नाम जाना-पहचाना है", "पूरा पता जांचें और परिचित कार्य-माध्यम से पुष्टि करें", "पासवर्ड से जवाब दें", "सभी सहकर्मियों को भेजें"], 1, "Lookalike sender addresses can impersonate trusted organizations. Verify the exact address and request.", "मिलते-जुलते ईमेल पते भरोसेमंद संस्थाओं की नकल कर सकते हैं। सही पता और अनुरोध जांचें।"),
    question("Medium", "An unexpected invoice attachment arrives from an unknown sender. What is the safest action?", "अनजान व्यक्ति से अप्रत्याशित बिल का अटैचमेंट आता है। सबसे सुरक्षित कदम क्या है?", ["Open it to see what it is", "Enable macros if asked", "Don't open it; verify the sender independently and report it", "Save it to a shared folder"], ["देखने के लिए खोलें", "कहने पर मैक्रो चालू करें", "न खोलें; भेजने वाले की अलग से पुष्टि करें और रिपोर्ट करें", "साझा फ़ोल्डर में सेव करें"], 2, "Unexpected attachments can contain malware. Confirm with the sender using a known contact method.", "अप्रत्याशित अटैचमेंट में मैलवेयर हो सकता है। ज्ञात संपर्क माध्यम से भेजने वाले की पुष्टि करें।"),
    question("Medium", "A message says your account will be deleted in ten minutes unless you sign in. What is the best response?", "संदेश कहता है कि दस मिनट में साइन-इन न करने पर खाता मिटा दिया जाएगा। सही प्रतिक्रिया क्या है?", ["Use its sign-in button", "Visit the service using its official app or saved address", "Send your password to support", "Ignore browser security warnings"], ["उसके साइन-इन बटन का उपयोग करें", "आधिकारिक ऐप या सुरक्षित पते से सेवा खोलें", "सपोर्ट को पासवर्ड भेजें", "ब्राउज़र चेतावनियों को अनदेखा करें"], 1, "Fear and urgency are used to make people click fake login links. Navigate to the service independently.", "डर और जल्दबाजी से नकली लॉगिन लिंक पर क्लिक करवाया जाता है। सेवा को स्वयं आधिकारिक तरीके से खोलें।"),
    question("Hard", "You entered your password on a page reached through a suspicious email. What should you do first?", "संदिग्ध ईमेल के लिंक से खुले पेज पर आपने पासवर्ड दर्ज कर दिया। सबसे पहले क्या करें?", ["Wait to see if anything happens", "Change it immediately on the real site and secure any reused accounts", "Reply to the email", "Delete your browser"], ["कुछ होने की प्रतीक्षा करें", "असली वेबसाइट पर तुरंत पासवर्ड बदलें और दोबारा इस्तेमाल किए खातों को सुरक्षित करें", "ईमेल का जवाब दें", "ब्राउज़र मिटा दें"], 1, "Changing the exposed password promptly limits misuse; also enable MFA and report the incident.", "उजागर पासवर्ड तुरंत बदलने से दुरुपयोग सीमित होता है; MFA चालू करें और घटना की रिपोर्ट करें।"),
    question("Easy", "A coworker sends an unusual request for gift cards from a new email address. What should you do?", "सहकर्मी के नाम से नए ईमेल पते पर गिफ्ट कार्ड खरीदने का असामान्य अनुरोध आता है। क्या करें?", ["Buy them quickly", "Reply asking for their password", "Confirm with the coworker through a known channel", "Send the gift card codes"], ["जल्दी खरीदें", "उनका पासवर्ड मांगकर जवाब दें", "ज्ञात माध्यम से सहकर्मी से पुष्टि करें", "गिफ्ट कार्ड कोड भेजें"], 2, "Compromised or spoofed accounts can impersonate colleagues. Verify unusual requests separately.", "हैक या नकली खातों से सहकर्मियों का रूप लिया जा सकता है। असामान्य अनुरोध की अलग से पुष्टि करें।"),
    question("Medium", "A login page reached from an email asks for your password and recovery code together. What should you do?", "ईमेल से खुले लॉगिन पेज पर पासवर्ड और रिकवरी कोड दोनों मांगे जाते हैं। क्या करें?", ["Enter both to avoid losing access", "Close it and sign in through the official app or site", "Send the recovery code to the sender", "Use the page on another device"], ["एक्सेस बचाने के लिए दोनों दर्ज करें", "पेज बंद करें और आधिकारिक ऐप या वेबसाइट से लॉगिन करें", "भेजने वाले को रिकवरी कोड भेजें", "दूसरे डिवाइस पर पेज खोलें"], 1, "Recovery codes are sensitive credentials. Only use them on the genuine service you navigated to yourself.", "रिकवरी कोड संवेदनशील प्रमाण होते हैं। इन्हें केवल स्वयं खोली गई असली सेवा पर उपयोग करें।"),
    question("Easy", "What should you do with a suspicious phishing message at work?", "काम पर मिले संदिग्ध फ़िशिंग संदेश के साथ क्या करें?", ["Forward it to everyone", "Use the organization's report-phishing process", "Click links to investigate", "Delete it without telling anyone"], ["इसे सभी को भेजें", "संस्था की फ़िशिंग रिपोर्ट प्रक्रिया अपनाएं", "जांचने के लिए लिंक खोलें", "किसी को बताए बिना मिटा दें"], 1, "Reporting helps security teams block similar messages and protect other people.", "रिपोर्ट करने से सुरक्षा टीम मिलते-जुलते संदेश रोककर दूसरों को सुरक्षित कर सकती है।"),
  ]),
  category("otp-banking", "OTP & Banking Fraud", "OTP और बैंकिंग धोखाधड़ी", [
    question("Easy", "A caller claiming to be from your bank asks for an OTP to stop a transaction. What should you do?", "बैंक का कर्मचारी बताने वाला व्यक्ति लेनदेन रोकने के लिए OTP मांगता है। क्या करें?", ["Share it to stop the transaction", "Share only the first digits", "Never share it; contact the bank using its official number", "Ask them to send another OTP"], ["लेनदेन रोकने के लिए OTP दें", "केवल शुरुआती अंक दें", "OTP साझा न करें; बैंक के आधिकारिक नंबर पर संपर्क करें", "दूसरा OTP भेजने को कहें"], 2, "Banks do not need your OTP over a call. Contact the bank yourself through a trusted channel.", "बैंक को फोन पर आपका OTP नहीं चाहिए। विश्वसनीय माध्यम से स्वयं बैंक से संपर्क करें।"),
    question("Easy", "You receive an OTP for a transaction you did not start. What is the safest response?", "ऐसे लेनदेन का OTP आता है जिसे आपने शुरू नहीं किया। सबसे सुरक्षित कदम क्या है?", ["Tell the caller who asks about it", "Do not share it; check your account through the official app and contact the bank", "Reply to the SMS", "Forward it to a friend"], ["पूछने वाले कॉलर को बताएं", "साझा न करें; आधिकारिक ऐप में खाता जांचें और बैंक से संपर्क करें", "SMS का जवाब दें", "दोस्त को भेजें"], 1, "An unexpected OTP may indicate an attempted transaction. Never disclose it and contact the bank.", "अनपेक्षित OTP से लेनदेन का प्रयास पता चल सकता है। इसे साझा न करें और बैंक से संपर्क करें।"),
    question("Medium", "Someone asks you to install an app to complete a KYC update over the phone. What should you do?", "फोन पर KYC अपडेट पूरा करने के लिए कोई ऐप इंस्टॉल करने को कहता है। क्या करें?", ["Install it and share your screen", "Install it only if they know your name", "Decline and verify KYC requirements through the official bank app or branch", "Give them remote access"], ["इंस्टॉल करके स्क्रीन साझा करें", "नाम पता होने पर इंस्टॉल करें", "मना करें और आधिकारिक बैंक ऐप या शाखा से KYC की पुष्टि करें", "रिमोट एक्सेस दें"], 2, "Unsolicited apps can enable remote control or steal data. Verify requests directly with the bank.", "अनचाहे ऐप रिमोट नियंत्रण या डेटा चोरी कर सकते हैं। अनुरोध की सीधे बैंक से पुष्टि करें।"),
    question("Easy", "A text says your debit card will be blocked and asks you to call a number in the message. What should you do?", "संदेश कहता है कि आपका डेबिट कार्ड बंद होगा और उसी में दिए नंबर पर कॉल करने को कहता है। क्या करें?", ["Call the number immediately", "Use the number printed on your card or the bank's official website", "Send your PIN by text", "Click any link in the message"], ["तुरंत उसी नंबर पर कॉल करें", "कार्ड पर छपे नंबर या बैंक की आधिकारिक वेबसाइट का नंबर उपयोग करें", "PIN संदेश में भेजें", "संदेश का कोई भी लिंक खोलें"], 1, "Use contact details you obtain independently, not numbers supplied in suspicious messages.", "संदिग्ध संदेश में दिए नंबर के बजाय संपर्क विवरण स्वयं आधिकारिक स्रोत से लें।"),
    question("Medium", "A caller asks you to read out your card CVV to reverse a failed payment. What should you do?", "असफल भुगतान वापस करने के लिए कॉलर कार्ड का CVV बताने को कहता है। क्या करें?", ["Read it out", "Share it if they know the transaction amount", "Do not disclose it; check with your bank through an official channel", "Send a photo of the card"], ["CVV बता दें", "लेनदेन की राशि पता होने पर साझा करें", "न बताएं; आधिकारिक माध्यम से बैंक से जांचें", "कार्ड की फोटो भेजें"], 2, "Never disclose card security details to unsolicited callers. A refund does not require revealing your CVV.", "अनचाहे कॉल करने वालों को कार्ड सुरक्षा विवरण न बताएं। रिफंड के लिए CVV बताना आवश्यक नहीं है।"),
    question("Medium", "A person says they can raise your bank transfer limit if you share your net-banking password. What should you do?", "कोई कहता है कि नेट बैंकिंग पासवर्ड देने पर वह ट्रांसफर सीमा बढ़ा देगा। क्या करें?", ["Share it temporarily", "Share it after changing it", "Refuse and use the bank's official app, website, or branch", "Send only half the password"], ["अस्थायी रूप से साझा करें", "बदलने के बाद साझा करें", "मना करें और बैंक का आधिकारिक ऐप, वेबसाइट या शाखा उपयोग करें", "आधा पासवर्ड भेजें"], 2, "Legitimate bank staff will not ask for your password. Manage account changes through official banking channels.", "बैंक कर्मचारी आपका पासवर्ड नहीं मांगेंगे। खाते में बदलाव आधिकारिक बैंकिंग माध्यम से करें।"),
    question("Easy", "What should you do if you accidentally shared an OTP with a caller?", "यदि गलती से कॉलर को OTP बता दिया तो क्या करना चाहिए?", ["Wait until tomorrow", "Immediately contact the bank, block affected services if needed, and report the transaction", "Share the next OTP too", "Delete the call log"], ["कल तक प्रतीक्षा करें", "तुरंत बैंक से संपर्क करें, जरूरत हो तो सेवाएं ब्लॉक करें और लेनदेन रिपोर्ट करें", "अगला OTP भी साझा करें", "कॉल लॉग मिटा दें"], 1, "Fast reporting can help the bank respond to unauthorized activity and secure your account.", "जल्दी रिपोर्ट करने से बैंक अनधिकृत गतिविधि पर कार्रवाई कर सकता है और खाता सुरक्षित कर सकता है।"),
    question("Medium", "A caller asks you to keep a banking conversation secret from your family and bank staff. What does this suggest?", "कॉलर बैंकिंग बातचीत को परिवार और बैंक कर्मचारियों से गुप्त रखने को कहता है। यह किस बात का संकेत है?", ["It is a normal security process", "It may be an attempt to isolate and pressure you; end the call and verify independently", "They are protecting your account", "You should transfer money to a safe account"], ["यह सामान्य सुरक्षा प्रक्रिया है", "यह अलग-थलग कर दबाव बनाने का प्रयास हो सकता है; कॉल काटकर पुष्टि करें", "वे आपका खाता सुरक्षित कर रहे हैं", "सुरक्षित खाते में पैसे भेजें"], 1, "Secrecy and pressure are manipulation tactics. Pause and check the claim with the bank using an official channel.", "गोपनीयता और दबाव हेरफेर के तरीके हैं। रुकें और आधिकारिक माध्यम से बैंक से जांचें।"),
    question("Hard", "You notice an unauthorized debit in your bank account. What should you do first?", "बैंक खाते में अनधिकृत कटौती दिखती है। सबसे पहले क्या करें?", ["Delete the notification", "Contact the bank immediately to block/report it and report cyber fraud through official channels", "Wait for the merchant to call", "Post your account number online"], ["सूचना मिटा दें", "तुरंत बैंक से संपर्क करके इसे ब्लॉक/रिपोर्ट करें और आधिकारिक माध्यम से साइबर धोखाधड़ी रिपोर्ट करें", "व्यापारी के कॉल की प्रतीक्षा करें", "खाता नंबर ऑनलाइन पोस्ट करें"], 1, "Promptly contact your bank and report suspected financial cybercrime using official channels.", "तुरंत बैंक से संपर्क करें और आधिकारिक माध्यम से संदिग्ध वित्तीय साइबर अपराध की रिपोर्ट करें।"),
    question("Easy", "How should you handle a message asking you to update banking details through an unfamiliar link?", "बैंकिंग विवरण अनजान लिंक से अपडेट करने को कहने वाला संदेश कैसे संभालें?", ["Open the link on mobile data", "Enter details only if the page has a bank logo", "Ignore the link and check using the bank's official app or website", "Send details by reply"], ["मोबाइल डेटा पर लिंक खोलें", "बैंक का लोगो होने पर जानकारी भरें", "लिंक न खोलें; बैंक के आधिकारिक ऐप या वेबसाइट से जांचें", "जवाब में विवरण भेजें"], 2, "Logos can be copied. Access your bank independently using its official app or known address.", "लोगो की नकल हो सकती है। बैंक का आधिकारिक ऐप या ज्ञात पता स्वयं खोलें।"),
  ]),
  category("upi", "UPI Scams", "UPI धोखाधड़ी", [
    question("Easy", "A buyer says you must enter your UPI PIN to receive their payment. What should you do?", "खरीदार कहता है कि भुगतान पाने के लिए UPI PIN डालना होगा। क्या करें?", ["Enter the PIN", "Scan their QR and enter the PIN", "Refuse; receiving money does not require entering your UPI PIN", "Share the PIN with the buyer"], ["PIN डालें", "QR स्कैन करके PIN डालें", "मना करें; पैसे पाने के लिए UPI PIN डालना नहीं पड़ता", "खरीदार को PIN बताएं"], 2, "A UPI PIN authorizes money leaving your account; it is not needed to receive money.", "UPI PIN से आपके खाते से पैसे भेजे जाते हैं; पैसे पाने के लिए इसकी जरूरत नहीं होती।"),
    question("Easy", "A collect request appears in your UPI app from an unknown person. What should you do?", "UPI ऐप में अनजान व्यक्ति से पैसे मांगने का अनुरोध आता है। क्या करें?", ["Approve it to receive money", "Check the amount and requester; decline if you did not expect it", "Enter your PIN to see who sent it", "Forward it to a contact"], ["पैसे पाने के लिए स्वीकार करें", "राशि और अनुरोधकर्ता जांचें; अनपेक्षित हो तो अस्वीकार करें", "भेजने वाले को देखने के लिए PIN डालें", "संपर्क को भेजें"], 1, "A collect request asks you to pay. Approve only if you recognize and intend the payment.", "पैसे मांगने का अनुरोध आपसे भुगतान करने को कहता है। केवल पहचानने और भुगतान करने का इरादा होने पर स्वीकार करें।"),
    question("Medium", "Someone sends a screenshot claiming a UPI payment is complete, but no credit appears in your app. What should you trust?", "कोई UPI भुगतान पूरा होने का स्क्रीनशॉट भेजता है, लेकिन ऐप में पैसे नहीं आए। किस पर भरोसा करें?", ["The screenshot", "Their message", "Your bank or UPI app transaction history", "A confirmation call"], ["स्क्रीनशॉट पर", "उनके संदेश पर", "अपने बैंक या UPI ऐप के लेनदेन इतिहास पर", "पुष्टि कॉल पर"], 2, "Screenshots can be altered. Confirm payments in your own bank or UPI transaction history.", "स्क्रीनशॉट बदले जा सकते हैं। अपने बैंक या UPI ऐप के लेनदेन इतिहास में भुगतान जांचें।"),
    question("Medium", "A stranger offers to help reverse a UPI payment and asks you to share your screen. What should you do?", "अजनबी UPI भुगतान वापस कराने में मदद के नाम पर स्क्रीन साझा करने को कहता है। क्या करें?", ["Share it while hiding your balance", "Decline and contact your bank or UPI app's official support", "Install their screen-sharing app", "Tell them your UPI PIN"], ["बैलेंस छिपाकर साझा करें", "मना करें और बैंक या UPI ऐप के आधिकारिक सपोर्ट से संपर्क करें", "उनका स्क्रीन शेयरिंग ऐप इंस्टॉल करें", "UPI PIN बताएं"], 1, "Screen sharing can expose sensitive information and allow manipulation. Use official support.", "स्क्रीन साझा करने से संवेदनशील जानकारी उजागर और हेरफेर हो सकती है। आधिकारिक सहायता लें।"),
    question("Easy", "You accidentally paid the wrong UPI ID. What is the appropriate next step?", "गलती से गलत UPI ID पर भुगतान हो गया। अगला सही कदम क्या है?", ["Pay again to cancel it", "Contact your bank or UPI app promptly and use its dispute process", "Ask a stranger online to recover it", "Share your PIN with the recipient"], ["रद्द करने के लिए फिर भुगतान करें", "तुरंत बैंक या UPI ऐप से संपर्क करके विवाद प्रक्रिया अपनाएं", "ऑनलाइन अजनबी से वापस दिलाने को कहें", "प्राप्तकर्ता को PIN बताएं"], 1, "Contact your bank or app provider quickly; never pay a third party promising guaranteed recovery.", "जल्दी बैंक या ऐप प्रदाता से संपर्क करें; पैसे वापस दिलाने का वादा करने वाले तीसरे पक्ष को भुगतान न करें।"),
    question("Medium", "A merchant asks you to scan a QR code to receive a refund. The app displays a payment screen. What should you do?", "व्यापारी रिफंड पाने के लिए QR स्कैन करने को कहता है, लेकिन ऐप भुगतान स्क्रीन दिखाता है। क्या करें?", ["Enter your PIN to receive the refund", "Stop and verify with the merchant through a trusted channel", "Approve it because the amount is small", "Share the screen with the merchant"], ["रिफंड पाने के लिए PIN डालें", "रुकें और विश्वसनीय माध्यम से व्यापारी की पुष्टि करें", "राशि कम है इसलिए स्वीकार करें", "व्यापारी से स्क्रीन साझा करें"], 1, "Review the transaction wording and recipient. A payment request is not a refund credit.", "लेनदेन का विवरण और प्राप्तकर्ता जांचें। भुगतान अनुरोध रिफंड जमा होना नहीं है।"),
    question("Easy", "Which detail should you verify before approving a UPI payment?", "UPI भुगतान स्वीकार करने से पहले कौन सा विवरण जांचना चाहिए?", ["Only the app color", "Recipient name and amount shown in the app", "The sender's profile photo", "The number of messages received"], ["केवल ऐप का रंग", "ऐप में दिख रहा प्राप्तकर्ता का नाम और राशि", "भेजने वाले की प्रोफाइल फोटो", "मिले संदेशों की संख्या"], 1, "Always check the recipient and amount on the confirmation screen before entering your PIN.", "PIN डालने से पहले पुष्टि स्क्रीन पर प्राप्तकर्ता और राशि हमेशा जांचें।"),
    question("Medium", "A caller says to transfer your money to a 'safe account' to protect it from fraud. What should you do?", "कॉलर धोखाधड़ी से बचाने के लिए पैसे 'सुरक्षित खाते' में भेजने को कहता है। क्या करें?", ["Transfer a small test amount", "Do not transfer; hang up and call your bank using its official number", "Ask them to send a QR code", "Share your UPI PIN first"], ["पहले थोड़ी रकम भेजें", "पैसे न भेजें; कॉल काटकर बैंक के आधिकारिक नंबर पर कॉल करें", "QR कोड भेजने को कहें", "पहले UPI PIN साझा करें"], 1, "Fraudsters use fake safe-account stories to steal money. Banks do not ask customers to move funds this way.", "धोखेबाज पैसे चुराने के लिए नकली सुरक्षित-खाते की कहानी बताते हैं। बैंक इस तरह पैसे भेजने को नहीं कहते।"),
    question("Hard", "You approved an unknown UPI collect request and money was debited. What should you do?", "अनजान UPI अनुरोध स्वीकार किया और पैसे कट गए। क्या करें?", ["Wait a few days", "Contact your bank and UPI provider immediately and report the fraud", "Send more money to reverse it", "Delete the UPI app"], ["कुछ दिन प्रतीक्षा करें", "तुरंत बैंक और UPI प्रदाता से संपर्क करें और धोखाधड़ी रिपोर्ट करें", "वापस पाने के लिए और पैसे भेजें", "UPI ऐप मिटा दें"], 1, "Promptly report unauthorized debits to your bank and use official reporting channels.", "अनधिकृत कटौती तुरंत बैंक को बताएं और आधिकारिक रिपोर्टिंग माध्यम अपनाएं।"),
    question("Easy", "Someone requests your UPI PIN to send you money. What is the correct response?", "कोई आपको पैसे भेजने के लिए UPI PIN मांगता है। सही प्रतिक्रिया क्या है?", ["Share it once", "Share only the last digit", "Never share it; a sender does not need your PIN", "Write it on the payment note"], ["एक बार बता दें", "केवल अंतिम अंक बताएं", "कभी साझा न करें; भेजने वाले को PIN नहीं चाहिए", "भुगतान नोट में लिखें"], 2, "Keep your UPI PIN secret. It authorizes payments from your account.", "UPI PIN गोपनीय रखें। इससे आपके खाते से भुगतान अधिकृत होता है।"),
  ]),
  category("passwords", "Passwords", "पासवर्ड", [
    question("Easy", "Which password practice is safest?", "पासवर्ड का कौन सा तरीका सबसे सुरक्षित है?", ["Reuse one password everywhere", "Use a long, unique password for each account", "Use your name and birth year", "Share passwords with friends"], ["हर जगह एक पासवर्ड रखें", "हर खाते के लिए लंबा और अलग पासवर्ड रखें", "नाम और जन्म वर्ष उपयोग करें", "दोस्तों को पासवर्ड बताएं"], 1, "Unique passwords prevent one exposed account from unlocking others.", "अलग-अलग पासवर्ड से एक खाते की जानकारी लीक होने पर अन्य खाते सुरक्षित रहते हैं।"),
    question("Easy", "How can a password manager help?", "पासवर्ड मैनेजर कैसे मदद कर सकता है?", ["It makes every password public", "It stores and generates unique passwords securely", "It removes the need to secure your device", "It shares passwords automatically with callers"], ["यह सभी पासवर्ड सार्वजनिक करता है", "यह अलग पासवर्ड सुरक्षित रख और बना सकता है", "डिवाइस सुरक्षित करने की जरूरत खत्म करता है", "कॉलर को अपने आप पासवर्ड भेजता है"], 1, "A reputable password manager can create and store unique passwords; protect it with a strong master password and MFA.", "विश्वसनीय पासवर्ड मैनेजर अलग पासवर्ड बना और रख सकता है; इसे मजबूत मास्टर पासवर्ड और MFA से सुरक्षित करें।"),
    question("Medium", "You receive an alert that your password appeared in a data breach. What should you do?", "सूचना मिलती है कि आपका पासवर्ड डेटा लीक में मिला है। क्या करें?", ["Keep using it until prompted", "Change it on the affected account and anywhere it was reused", "Post it in a forum to check", "Change only one character"], ["कहने तक उपयोग करते रहें", "प्रभावित खाते और जहां दोबारा उपयोग किया वहां बदलें", "जांचने के लिए फोरम पर डालें", "केवल एक अक्षर बदलें"], 1, "Replace exposed passwords with unique ones and enable multi-factor authentication.", "उजागर पासवर्ड को अलग पासवर्ड से बदलें और मल्टी-फैक्टर प्रमाणीकरण चालू करें।"),
    question("Easy", "Which is a safer way to create a memorable password?", "याद रखने योग्य पासवर्ड बनाने का सुरक्षित तरीका कौन सा है?", ["A common quote and your name", "A long, unique passphrase not used elsewhere", "Your phone number", "The word 'password' with 1 added"], ["आम कहावत और आपका नाम", "लंबा, अलग पासफ़्रेज़ जिसका उपयोग कहीं और न हो", "आपका फोन नंबर", "password के बाद 1 जोड़ें"], 1, "Long, unique passphrases are harder to guess, especially when not reused.", "लंबे और अलग पासफ़्रेज़ का अनुमान लगाना कठिन होता है, खासकर जब वे दोबारा उपयोग न हों।"),
    question("Medium", "A website asks you to set a security question. Which answer is safest?", "वेबसाइट सुरक्षा प्रश्न का उत्तर मांगती है। सबसे सुरक्षित उत्तर कौन सा है?", ["A fact visible on your social profile", "A truthful public fact", "A unique answer stored securely like a password", "Your account password"], ["सोशल प्रोफाइल पर दिखने वाला तथ्य", "सार्वजनिक सच्चा तथ्य", "पासवर्ड की तरह सुरक्षित रखा अनोखा उत्तर", "खाते का पासवर्ड"], 2, "Security answers can be guessed from public details; treat them as secret credentials.", "सुरक्षा उत्तर सार्वजनिक जानकारी से अनुमानित हो सकते हैं; इन्हें गुप्त प्रमाण की तरह रखें।"),
    question("Easy", "Where should you store a recovery code?", "रिकवरी कोड कहां रखना चाहिए?", ["In a public post", "In a secure password manager or another protected offline location", "In a shared work chat", "On a note attached to your device"], ["सार्वजनिक पोस्ट में", "सुरक्षित पासवर्ड मैनेजर या संरक्षित ऑफलाइन जगह में", "साझा कार्य चैट में", "डिवाइस पर चिपकी पर्ची पर"], 1, "Recovery codes can bypass account protections, so keep them private and securely stored.", "रिकवरी कोड खाते की सुरक्षा पार कर सकते हैं, इसलिए निजी और सुरक्षित रखें।"),
    question("Medium", "A support agent asks you to tell them your account password to fix a problem. What should you do?", "सपोर्ट एजेंट समस्या ठीक करने के लिए खाते का पासवर्ड बताने को कहता है। क्या करें?", ["Tell them if they have a company badge", "Refuse and use the service's official support process", "Send it in a private message", "Change it to a simple one first"], ["कंपनी बैज हो तो बता दें", "मना करें और सेवा की आधिकारिक सपोर्ट प्रक्रिया अपनाएं", "निजी संदेश में भेजें", "पहले आसान पासवर्ड रखें"], 1, "Legitimate support should not need your password. Never disclose it to another person.", "असली सहायता टीम को आपका पासवर्ड नहीं चाहिए। इसे किसी अन्य व्यक्ति को न बताएं।"),
    question("Easy", "What does multi-factor authentication add to an account?", "मल्टी-फैक्टर प्रमाणीकरण खाते में क्या जोड़ता है?", ["Another independent verification step", "A public password", "A way to skip updates", "Automatic account sharing"], ["एक अतिरिक्त स्वतंत्र सत्यापन चरण", "सार्वजनिक पासवर्ड", "अपडेट छोड़ने का तरीका", "खाता अपने आप साझा करना"], 0, "MFA requires another proof of identity, making a stolen password less useful to an attacker.", "MFA पहचान का एक और प्रमाण मांगता है, जिससे चोरी हुआ पासवर्ड हमलावर के कम काम आता है।"),
    question("Medium", "You are creating a password for an important account. Which should you avoid?", "महत्वपूर्ण खाते के लिए पासवर्ड बनाते समय किससे बचें?", ["Using a unique passphrase", "Using a password manager", "Using the same password as your email account", "Enabling MFA"], ["अलग पासफ़्रेज़ उपयोग करना", "पासवर्ड मैनेजर उपयोग करना", "ईमेल खाते वाला ही पासवर्ड रखना", "MFA चालू करना"], 2, "Reusing a password lets an attacker try leaked credentials on other services.", "पासवर्ड दोहराने से हमलावर लीक प्रमाणों को अन्य सेवाओं पर आजमा सकते हैं।"),
    question("Hard", "You suspect someone else knows your password. What is the best response?", "आपको संदेह है कि किसी और को आपका पासवर्ड पता है। क्या करें?", ["Wait for them to log in", "Change it from the official service, sign out other sessions, and enable MFA", "Send them a warning with your new password", "Disable account alerts"], ["उनके लॉगिन की प्रतीक्षा करें", "आधिकारिक सेवा पर बदलें, अन्य सत्र बंद करें और MFA चालू करें", "नया पासवर्ड उन्हें चेतावनी में भेजें", "खाता अलर्ट बंद करें"], 1, "Secure the account promptly, end unknown sessions, and use MFA to reduce further access.", "खाते को तुरंत सुरक्षित करें, अनजान सत्र बंद करें और आगे के एक्सेस को रोकने के लिए MFA उपयोग करें।"),
  ]),
  category("social-engineering", "Social Engineering", "सोशल इंजीनियरिंग", [
    question("Easy", "A caller pressures you to act immediately and keep the call secret. What should you do?", "कॉलर तुरंत कार्रवाई करने और कॉल गुप्त रखने का दबाव डालता है। क्या करें?", ["Follow the instructions", "Pause, end the call, and verify through an official contact", "Give a small amount first", "Share an OTP to confirm identity"], ["निर्देश मानें", "रुकें, कॉल समाप्त करें और आधिकारिक संपर्क से पुष्टि करें", "पहले थोड़ी राशि दें", "पहचान पुष्टि के लिए OTP साझा करें"], 1, "Urgency and secrecy are common manipulation tactics. Take time and verify independently.", "जल्दबाजी और गोपनीयता हेरफेर के आम तरीके हैं। समय लें और स्वयं पुष्टि करें।"),
    question("Medium", "Someone follows you through a secure office door saying they forgot their badge. What should you do?", "कोई बैज भूलने की बात कहकर सुरक्षित कार्यालय के दरवाजे से आपके पीछे अंदर आता है। क्या करें?", ["Hold the door because they look familiar", "Politely direct them to reception or the approved access process", "Share your badge", "Let them use your computer"], ["पहचाने लगते हैं इसलिए दरवाजा रोकें", "उन्हें रिसेप्शन या स्वीकृत प्रवेश प्रक्रिया की ओर भेजें", "अपना बैज दें", "कंप्यूटर उपयोग करने दें"], 1, "Tailgating bypasses physical access controls. Follow your organization's visitor procedures.", "पीछे-पीछे प्रवेश करके भौतिक सुरक्षा तोड़ी जा सकती है। संस्था की आगंतुक प्रक्रिया अपनाएं।"),
    question("Easy", "A person claiming to be IT asks for your login code to fix your account. What should you do?", "IT कर्मचारी बताने वाला व्यक्ति खाता ठीक करने के लिए लॉगिन कोड मांगता है। क्या करें?", ["Give it to them", "Refuse and contact IT through a known support channel", "Send it after changing your password", "Read only half of it"], ["कोड दे दें", "मना करें और ज्ञात सहायता माध्यम से IT से संपर्क करें", "पासवर्ड बदलकर कोड भेजें", "आधा कोड बताएं"], 1, "One-time login codes should not be shared. Verify support requests using a known channel.", "एक बार उपयोग होने वाले लॉगिन कोड साझा न करें। ज्ञात माध्यम से सहायता अनुरोध की पुष्टि करें।"),
    question("Medium", "A stranger offers a free gift if you scan your badge and share your staff details. What is safest?", "अजनबी बैज स्कैन करके कर्मचारी विवरण देने पर मुफ्त उपहार देता है। सुरक्षित कदम क्या है?", ["Share details because the gift is free", "Decline and check the promotion with your organization", "Send a photo of your badge", "Use a personal account to share it"], ["उपहार मुफ्त है इसलिए विवरण दें", "मना करें और संस्था से प्रचार की पुष्टि करें", "बैज की फोटो भेजें", "व्यक्तिगत खाते से साझा करें"], 1, "Unverified offers may be used to collect identity or workplace information.", "अपुष्ट प्रस्तावों से पहचान या कार्यस्थल की जानकारी जुटाई जा सकती है।"),
    question("Medium", "A caller knows public details about you and asks for a confidential code. What should you remember?", "कॉलर को आपके सार्वजनिक विवरण पता हैं और वह गोपनीय कोड मांगता है। क्या याद रखें?", ["Knowing details proves they are genuine", "Public information can be used to sound convincing; never share the code", "Give the code if they say your name", "Ask them to guess your password"], ["विवरण पता होना असली होने का प्रमाण है", "सार्वजनिक जानकारी से विश्वसनीय लगा जा सकता है; कोड साझा न करें", "नाम बोलें तो कोड दें", "पासवर्ड का अनुमान लगाने को कहें"], 1, "Personal details may be publicly available and do not authenticate a caller.", "व्यक्तिगत विवरण सार्वजनिक हो सकते हैं और कॉलर की पहचान प्रमाणित नहीं करते।"),
    question("Easy", "A delivery worker asks you to tell them a verification code sent to your phone. What should you do?", "डिलीवरी कर्मी फोन पर आए सत्यापन कोड को बताने को कहता है। क्या करें?", ["Share it without reading the message", "Read the code and decide later", "Check the message purpose; never share account or payment codes", "Send all recent codes"], ["संदेश पढ़े बिना साझा करें", "कोड पढ़कर बाद में निर्णय लें", "संदेश का उद्देश्य जांचें; खाता या भुगतान कोड साझा न करें", "सभी हाल के कोड भेजें"], 2, "Codes may authorize account access or payments. Understand the purpose and keep sensitive codes private.", "कोड खाते का एक्सेस या भुगतान अधिकृत कर सकते हैं। उद्देश्य समझें और संवेदनशील कोड निजी रखें।"),
    question("Hard", "A manager emails an unusual request to urgently send confidential files to a new address. What should you do?", "प्रबंधक के नाम से गोपनीय फाइलें नए पते पर तुरंत भेजने का असामान्य ईमेल आता है। क्या करें?", ["Send them immediately", "Verify the request using a separate known communication channel", "Reply asking for their password", "Upload them to a public link"], ["तुरंत भेजें", "अलग ज्ञात संचार माध्यम से अनुरोध की पुष्टि करें", "पासवर्ड मांगकर जवाब दें", "सार्वजनिक लिंक पर अपलोड करें"], 1, "Attackers impersonate authority to create urgency. Independently confirm sensitive requests before acting.", "हमलावर जल्दबाजी के लिए अधिकारी होने का रूप लेते हैं। संवेदनशील अनुरोध पर कार्रवाई से पहले अलग से पुष्टि करें।"),
    question("Medium", "A caller says you will be arrested unless you transfer money immediately. What should you do?", "कॉलर कहता है कि तुरंत पैसे न भेजने पर आपको गिरफ्तार कर लिया जाएगा। क्या करें?", ["Transfer money to settle it", "Stay calm, end the call, and verify with the relevant agency using official details", "Share your banking password", "Follow instructions and do not tell anyone"], ["मामला निपटाने के लिए पैसे भेजें", "शांत रहें, कॉल काटें और आधिकारिक विवरण से संबंधित एजेंसी की पुष्टि करें", "बैंक पासवर्ड साझा करें", "निर्देश मानें और किसी को न बताएं"], 1, "Threats and demands for immediate payment are coercive tactics. Verify independently and seek trusted help.", "धमकी और तुरंत भुगतान की मांग दबाव के तरीके हैं। स्वयं पुष्टि करें और विश्वसनीय सहायता लें।"),
    question("Easy", "A caller asks you to install remote-access software so they can secure your computer. What is safest?", "कॉलर कंप्यूटर सुरक्षित करने के लिए रिमोट-एक्सेस सॉफ्टवेयर इंस्टॉल करने को कहता है। सुरक्षित तरीका क्या है?", ["Install it and share access", "Decline and contact the organization using its official support details", "Install it but hide your files", "Give access for five minutes"], ["इंस्टॉल करके एक्सेस दें", "मना करें और आधिकारिक सहायता विवरण से संस्था से संपर्क करें", "इंस्टॉल करें लेकिन फाइलें छिपाएं", "पांच मिनट का एक्सेस दें"], 1, "Unsolicited remote access can expose data and control your device. Verify support requests directly.", "अनचाहा रिमोट एक्सेस डेटा उजागर कर सकता है और डिवाइस नियंत्रित कर सकता है। सहायता अनुरोध की सीधे पुष्टि करें।"),
    question("Medium", "Someone asks you to bypass a normal approval step because the request is confidential. What should you do?", "कोई अनुरोध गोपनीय बताकर सामान्य स्वीकृति चरण छोड़ने को कहता है। क्या करें?", ["Skip it to be helpful", "Follow established procedures and confirm with an authorized person", "Share your own approval credentials", "Ask a coworker to approve without details"], ["मदद के लिए चरण छोड़ें", "निर्धारित प्रक्रिया अपनाएं और अधिकृत व्यक्ति से पुष्टि करें", "अपने स्वीकृति प्रमाण साझा करें", "सहकर्मी से बिना विवरण मंजूरी लें"], 1, "Procedures help prevent impersonation and unauthorized actions; don't bypass them under pressure.", "प्रक्रियाएं पहचान की नकल और अनधिकृत कार्रवाई रोकती हैं; दबाव में इन्हें न छोड़ें।"),
  ]),
  category("fake-websites", "Fake Websites", "नकली वेबसाइट", [
    question("Easy", "What is the safest way to open your bank's website?", "बैंक की वेबसाइट खोलने का सबसे सुरक्षित तरीका क्या है?", ["Click a link in an unexpected text", "Type the known address yourself or use the official app", "Use the first advertisement", "Search for a login page in a message"], ["अनपेक्षित संदेश का लिंक खोलें", "ज्ञात पता स्वयं टाइप करें या आधिकारिक ऐप उपयोग करें", "पहले विज्ञापन का उपयोग करें", "संदेश में लॉगिन पेज खोजें"], 1, "Independent navigation reduces the risk of landing on a lookalike login page.", "स्वयं वेबसाइट खोलने से मिलते-जुलते नकली लॉगिन पेज का जोखिम घटता है।"),
    question("Medium", "A website URL has a misspelled brand name. What should you do?", "वेबसाइट URL में ब्रांड नाम की वर्तनी गलत है। क्या करें?", ["Log in if its design looks right", "Do not enter information; check the official address independently", "Share the URL with a friend to test it", "Ignore the spelling"], ["डिजाइन सही लगे तो लॉगिन करें", "जानकारी न भरें; आधिकारिक पता स्वयं जांचें", "जांचने के लिए दोस्त को URL भेजें", "वर्तनी अनदेखी करें"], 1, "Lookalike domains can impersonate real brands. Check the exact domain before entering data.", "मिलते-जुलते डोमेन असली ब्रांड की नकल कर सकते हैं। जानकारी भरने से पहले सही डोमेन जांचें।"),
    question("Easy", "Does a padlock icon alone prove that a website is legitimate?", "क्या केवल ताला आइकन यह साबित करता है कि वेबसाइट असली है?", ["Yes, always", "No; it indicates an encrypted connection, not that the site is trustworthy", "Yes, if the page has a logo", "Only on mobile"], ["हां, हमेशा", "नहीं; यह एन्क्रिप्टेड कनेक्शन बताता है, साइट की विश्वसनीयता नहीं", "हां, यदि लोगो है", "केवल मोबाइल पर"], 1, "HTTPS protects the connection but scammers can also use it. Verify the domain and source.", "HTTPS कनेक्शन सुरक्षित करता है, लेकिन धोखेबाज भी इसका उपयोग कर सकते हैं। डोमेन और स्रोत जांचें।"),
    question("Medium", "A store's URL uses a strange extra word before the brand name. What should you do?", "स्टोर URL में ब्रांड नाम से पहले एक अजीब अतिरिक्त शब्द है। क्या करें?", ["Assume it is a regional site", "Verify the domain from the brand's official source before buying", "Enter card details to test it", "Use it if a search ad shows it"], ["इसे क्षेत्रीय वेबसाइट मानें", "खरीदने से पहले ब्रांड के आधिकारिक स्रोत से डोमेन जांचें", "जांचने के लिए कार्ड विवरण भरें", "सर्च विज्ञापन में दिखे तो उपयोग करें"], 1, "Extra words and subdomains can disguise impersonation. Confirm the domain through the brand's official source.", "अतिरिक्त शब्द और सबडोमेन नकली पहचान छिपा सकते हैं। ब्रांड के आधिकारिक स्रोत से डोमेन पुष्टि करें।"),
    question("Easy", "A website shows a browser warning about an unsafe connection. What should you do?", "वेबसाइट पर असुरक्षित कनेक्शन की ब्राउज़र चेतावनी दिखती है। क्या करें?", ["Proceed and enter your password", "Stop and leave the site", "Disable browser security", "Use a different password there"], ["आगे बढ़कर पासवर्ड दर्ज करें", "रुकें और वेबसाइट छोड़ें", "ब्राउज़र सुरक्षा बंद करें", "वहां दूसरा पासवर्ड उपयोग करें"], 1, "Do not bypass security warnings, especially on pages requesting login or payment details.", "सुरक्षा चेतावनी को पार न करें, विशेषकर लॉगिन या भुगतान विवरण मांगने वाले पेज पर।"),
    question("Medium", "A website's contact page has no real business details and only a free email address. What should you do before paying?", "वेबसाइट पर वास्तविक संपर्क विवरण नहीं, केवल मुफ्त ईमेल पता है। भुगतान से पहले क्या करें?", ["Pay because prices are low", "Research the seller independently and use a trusted retailer if unsure", "Send payment by gift card", "Share identity documents"], ["कीमत कम है इसलिए भुगतान करें", "विक्रेता की स्वतंत्र जांच करें; संदेह हो तो विश्वसनीय विक्रेता चुनें", "गिफ्ट कार्ड से भुगतान करें", "पहचान दस्तावेज दें"], 1, "Missing or unverifiable contact details are a warning sign; research the business before purchasing.", "गायब या अपुष्ट संपर्क विवरण चेतावनी संकेत हैं; खरीदने से पहले व्यवसाय की जांच करें।"),
    question("Hard", "You entered your credentials on a fake login page. What should you do?", "नकली लॉगिन पेज पर आपने प्रमाण दर्ज किए। अब क्या करें?", ["Wait for an alert", "Change the password on the real service, secure reused accounts, and enable MFA", "Delete the browser history only", "Reply to the website"], ["अलर्ट की प्रतीक्षा करें", "असली सेवा पर पासवर्ड बदलें, दोहराए खाते सुरक्षित करें और MFA चालू करें", "केवल ब्राउज़र इतिहास मिटाएं", "वेबसाइट को जवाब दें"], 1, "Assume the credentials are exposed and secure affected accounts immediately.", "प्रमाण उजागर मानकर प्रभावित खातों को तुरंत सुरक्षित करें।"),
    question("Medium", "A search result is marked as an advertisement and leads to a bank login page. What is safest?", "सर्च परिणाम विज्ञापन के रूप में चिह्नित है और बैंक लॉगिन पेज पर ले जाता है। सुरक्षित तरीका क्या है?", ["Enter your details because it is at the top", "Use the bank's official app or type its known address instead", "Trust it if the logo is correct", "Share the link in a group"], ["सबसे ऊपर है इसलिए जानकारी भरें", "बैंक का आधिकारिक ऐप या ज्ञात पता स्वयं उपयोग करें", "लोगो सही है तो भरोसा करें", "लिंक समूह में भेजें"], 1, "Search ads can lead to impersonation sites. Navigate through a trusted, known route.", "सर्च विज्ञापन नकली साइट पर ले जा सकते हैं। विश्वसनीय ज्ञात माध्यम से वेबसाइट खोलें।"),
    question("Easy", "Before entering payment details, what should you check on a shopping website?", "शॉपिंग वेबसाइट पर भुगतान जानकारी भरने से पहले क्या जांचें?", ["Only its colors", "The exact domain, seller identity, and secure checkout details", "Whether it has a countdown timer", "If it asks for your email password"], ["केवल रंग", "सही डोमेन, विक्रेता की पहचान और सुरक्षित भुगतान विवरण", "काउंटडाउन टाइमर है या नहीं", "ईमेल पासवर्ड मांगा है या नहीं"], 1, "Check the exact address and seller; avoid pages asking for unrelated credentials.", "सही पता और विक्रेता जांचें; असंबंधित प्रमाण मांगने वाले पेज से बचें।"),
    question("Medium", "A link opens a site that redirects through several unfamiliar pages. What should you do?", "लिंक कई अनजान पेजों से होकर वेबसाइट खोलता है। क्या करें?", ["Continue to the final page", "Close it and access the service using its official address", "Enter a temporary password", "Allow all notifications"], ["अंतिम पेज तक जाएं", "बंद करें और आधिकारिक पते से सेवा खोलें", "अस्थायी पासवर्ड दर्ज करें", "सभी सूचनाएं अनुमति दें"], 1, "Unexpected redirects can lead to malicious or deceptive pages. Avoid them and navigate independently.", "अनपेक्षित रीडायरेक्ट हानिकारक या भ्रामक पेज पर ले जा सकते हैं। इनसे बचें और स्वयं वेबसाइट खोलें।"),
  ]),
  category("shopping", "Shopping Scams", "शॉपिंग धोखाधड़ी", [
    question("Easy", "An unknown shop offers a new phone at an unbelievable discount and requests payment to a personal UPI ID. What should you do?", "अनजान दुकान नया फोन अविश्वसनीय छूट पर देकर निजी UPI ID पर भुगतान मांगती है। क्या करें?", ["Pay quickly before the offer ends", "Verify the seller and use a trusted payment method or retailer", "Send your card PIN", "Pay and trust the receipt"], ["ऑफर खत्म होने से पहले भुगतान करें", "विक्रेता जांचें और विश्वसनीय भुगतान माध्यम या दुकान चुनें", "कार्ड PIN भेजें", "रसीद पर भरोसा करके भुगतान करें"], 1, "Extreme discounts and personal payment requests can signal a scam. Verify before paying.", "अत्यधिक छूट और निजी भुगतान अनुरोध धोखाधड़ी के संकेत हो सकते हैं। भुगतान से पहले जांचें।"),
    question("Medium", "A seller on social media insists on payment before sharing any product or business details. What is safest?", "सोशल मीडिया विक्रेता उत्पाद या व्यवसाय विवरण दिए बिना पहले भुगतान पर जोर देता है। सुरक्षित तरीका क्या है?", ["Pay a small deposit", "Ask for a secure platform checkout and verify seller history", "Send your ID as a guarantee", "Pay by gift card"], ["थोड़ी अग्रिम राशि दें", "सुरक्षित प्लेटफॉर्म भुगतान मांगें और विक्रेता का इतिहास जांचें", "गारंटी के लिए ID भेजें", "गिफ्ट कार्ड से भुगतान करें"], 1, "Use protected checkout methods and check seller reputation before sending money.", "सुरक्षित भुगतान और खरीदार सुरक्षा उपयोग करें; पैसे भेजने से पहले विक्रेता की प्रतिष्ठा जांचें।"),
    question("Easy", "A message says a parcel is held and asks you to pay a tiny fee through a link. What should you do?", "संदेश कहता है कि पार्सल रुका है और लिंक से छोटी फीस मांगता है। क्या करें?", ["Pay the fee", "Check tracking in the delivery company's official app or site", "Enter your card details to see the parcel", "Reply with your address and OTP"], ["फीस दें", "डिलीवरी कंपनी के आधिकारिक ऐप या साइट पर ट्रैकिंग जांचें", "पार्सल देखने के लिए कार्ड विवरण भरें", "पता और OTP जवाब में दें"], 1, "Unexpected delivery-fee links can be phishing. Verify the shipment with the official carrier.", "अनपेक्षित डिलीवरी फीस लिंक फ़िशिंग हो सकते हैं। आधिकारिक सेवा से शिपमेंट जांचें।"),
    question("Medium", "A seller asks you to pay outside a marketplace to get a lower price. What should you do?", "कम कीमत के लिए विक्रेता मार्केटप्लेस से बाहर भुगतान करने को कहता है। क्या करें?", ["Agree to save money", "Keep payment on the platform to retain buyer protections", "Send cash to a courier", "Share your account password"], ["पैसे बचाने के लिए मानें", "खरीदार सुरक्षा के लिए प्लेटफॉर्म पर भुगतान करें", "कूरियर को नकद भेजें", "खाता पासवर्ड बताएं"], 1, "Off-platform payments may remove dispute protections and make recovery difficult.", "प्लेटफॉर्म से बाहर भुगतान विवाद सुरक्षा हटा सकता है और पैसे वापस पाना कठिन करता है।"),
    question("Easy", "A website has many identical five-star reviews posted on the same day. What should you do?", "वेबसाइट पर एक ही दिन में कई समान पांच-सितारा समीक्षाएं हैं। क्या करें?", ["Assume the product is genuine", "Look for independent reviews and verify the seller", "Post your card number to ask", "Buy several items"], ["उत्पाद असली मानें", "स्वतंत्र समीक्षाएं खोजें और विक्रेता जांचें", "पूछने के लिए कार्ड नंबर पोस्ट करें", "कई सामान खरीदें"], 1, "Review patterns can be manipulated. Check independent sources and seller information.", "समीक्षाओं में हेरफेर हो सकता है। स्वतंत्र स्रोत और विक्रेता जानकारी जांचें।"),
    question("Medium", "A store asks for your email password to apply a discount. What should you do?", "छूट देने के लिए दुकान आपका ईमेल पासवर्ड मांगती है। क्या करें?", ["Provide it temporarily", "Do not share it; no legitimate store needs your email password", "Change it after purchase", "Give a password you use elsewhere"], ["अस्थायी रूप से दें", "साझा न करें; असली दुकान को ईमेल पासवर्ड नहीं चाहिए", "खरीद के बाद बदलें", "कहीं और उपयोग किया पासवर्ड दें"], 1, "Never disclose account passwords to sellers; use only the information needed for a purchase.", "विक्रेता को खाते का पासवर्ड कभी न बताएं; खरीद के लिए जरूरी जानकारी ही दें।"),
    question("Easy", "What should you do when a shopping site asks for a one-time banking OTP by phone?", "शॉपिंग साइट फोन पर बैंकिंग OTP मांगती है। क्या करें?", ["Read it aloud", "Do not share it; complete payment only through your bank's secure flow", "Send it in chat", "Share it if the caller knows the order"], ["फोन पर बता दें", "साझा न करें; बैंक की सुरक्षित प्रक्रिया से ही भुगतान करें", "चैट में भेजें", "ऑर्डर पता हो तो साझा करें"], 1, "Do not disclose OTPs to people; enter them only in the expected official payment flow you initiated.", "OTP किसी व्यक्ति को न बताएं; केवल अपने शुरू किए आधिकारिक भुगतान चरण में दर्ज करें।"),
    question("Hard", "You paid an online seller but received no confirmation or product. What should you do?", "ऑनलाइन विक्रेता को भुगतान किया, लेकिन पुष्टि या सामान नहीं मिला। क्या करें?", ["Pay again to confirm", "Contact the platform and payment provider through official channels and preserve records", "Send your PIN to the seller", "Delete the order details"], ["पुष्टि के लिए फिर भुगतान करें", "आधिकारिक माध्यम से प्लेटफॉर्म और भुगतान प्रदाता से संपर्क करें और रिकॉर्ड रखें", "विक्रेता को PIN भेजें", "ऑर्डर विवरण मिटाएं"], 1, "Preserve receipts and messages, report the issue to the platform and payment provider, and avoid further payments.", "रसीदें और संदेश सुरक्षित रखें, प्लेटफॉर्म और भुगतान प्रदाता को रिपोर्ट करें तथा आगे भुगतान न करें।"),
    question("Medium", "A seller asks for your card number, expiry, CVV, and bank OTP in a chat. What should you do?", "विक्रेता चैट में कार्ड नंबर, समाप्ति तारीख, CVV और बैंक OTP मांगता है। क्या करें?", ["Send them to complete checkout", "Refuse and use a secure checkout from a verified seller", "Send only the CVV", "Share details in a disappearing message"], ["चेकआउट के लिए भेजें", "मना करें और सत्यापित विक्रेता का सुरक्षित भुगतान उपयोग करें", "केवल CVV भेजें", "गायब होने वाले संदेश में भेजें"], 1, "Do not send payment credentials in chat. Use a secure payment page and never disclose OTPs.", "भुगतान प्रमाण चैट में न भेजें। सुरक्षित भुगतान पेज उपयोग करें और OTP कभी न बताएं।"),
    question("Easy", "How should you verify a return or refund message?", "रिटर्न या रिफंड संदेश की पुष्टि कैसे करें?", ["Click the link in the message", "Check the order in the retailer's official app or contact its verified support", "Share your bank PIN", "Install a refund app sent by the seller"], ["संदेश का लिंक खोलें", "रिटेलर के आधिकारिक ऐप में ऑर्डर जांचें या सत्यापित सहायता से संपर्क करें", "बैंक PIN साझा करें", "विक्रेता का भेजा रिफंड ऐप इंस्टॉल करें"], 1, "Use the retailer's official order page and support contacts to verify refunds.", "रिफंड की पुष्टि के लिए रिटेलर का आधिकारिक ऑर्डर पेज और सहायता संपर्क उपयोग करें।"),
  ]),
  category("public-wifi", "Public Wi-Fi", "सार्वजनिक Wi-Fi", [
    question("Easy", "What is safest when using open public Wi-Fi?", "खुले सार्वजनिक Wi-Fi पर सबसे सुरक्षित व्यवहार क्या है?", ["Access banking accounts", "Avoid sensitive logins and use a trusted mobile connection for important transactions", "Turn off device updates forever", "Share files with everyone"], ["बैंकिंग खाते खोलें", "संवेदनशील लॉगिन से बचें और जरूरी लेनदेन के लिए विश्वसनीय मोबाइल कनेक्शन लें", "डिवाइस अपडेट हमेशा बंद करें", "सभी के साथ फाइल साझा करें"], 1, "Avoid sensitive activity on networks you do not control; use a trusted connection when possible.", "अपने नियंत्रण से बाहर नेटवर्क पर संवेदनशील काम न करें; संभव हो तो विश्वसनीय कनेक्शन लें।"),
    question("Medium", "A Wi-Fi network named like a cafe's official network has no password. What should you do?", "कैफे के आधिकारिक नाम जैसा Wi-Fi नेटवर्क बिना पासवर्ड दिखता है। क्या करें?", ["Connect and enter account passwords", "Confirm the exact network name with staff before connecting", "Use the strongest signal regardless of name", "Turn on file sharing"], ["जुड़कर खाते के पासवर्ड भरें", "जुड़ने से पहले कर्मचारियों से सही नेटवर्क नाम पूछें", "नाम की परवाह किए बिना तेज सिग्नल चुनें", "फाइल शेयरिंग चालू करें"], 1, "A lookalike hotspot can capture traffic or imitate a legitimate network. Confirm the network with staff.", "नकली हॉटस्पॉट ट्रैफिक पकड़ या असली नेटवर्क की नकल कर सकता है। कर्मचारियों से नाम पुष्टि करें।"),
    question("Easy", "Should you allow your laptop to be discoverable on public Wi-Fi?", "क्या सार्वजनिक Wi-Fi पर लैपटॉप को खोजे जाने की अनुमति देनी चाहिए?", ["Yes, for convenience", "No; turn off discovery and file sharing on public networks", "Only when using banking", "Yes, if the network is free"], ["हां, सुविधा के लिए", "नहीं; सार्वजनिक नेटवर्क पर खोज और फाइल शेयरिंग बंद करें", "केवल बैंकिंग के समय", "हां, यदि नेटवर्क मुफ्त है"], 1, "Disabling discovery and sharing reduces exposure to nearby devices on public networks.", "खोज और साझाकरण बंद करने से सार्वजनिक नेटवर्क पर आसपास के उपकरणों के सामने जोखिम घटता है।"),
    question("Medium", "A public Wi-Fi login page asks for your email password. What should you do?", "सार्वजनिक Wi-Fi लॉगिन पेज ईमेल पासवर्ड मांगता है। क्या करें?", ["Enter it to connect", "Do not provide it; use a legitimate access method or mobile data", "Use your bank password instead", "Share it only once"], ["कनेक्ट होने के लिए भरें", "न दें; वैध एक्सेस तरीका या मोबाइल डेटा उपयोग करें", "बैंक पासवर्ड उपयोग करें", "केवल एक बार साझा करें"], 1, "A hotspot should not need your email account password. Avoid giving unrelated credentials.", "हॉटस्पॉट को ईमेल खाते का पासवर्ड नहीं चाहिए। असंबंधित प्रमाण न दें।"),
    question("Easy", "What should you do after using a public Wi-Fi hotspot?", "सार्वजनिक Wi-Fi हॉटस्पॉट उपयोग करने के बाद क्या करें?", ["Leave auto-connect enabled", "Disconnect and remove the network if you no longer need it", "Keep file sharing on", "Save banking passwords on the shared device"], ["ऑटो-कनेक्ट चालू छोड़ें", "डिस्कनेक्ट करें और जरूरत न हो तो नेटवर्क हटाएं", "फाइल शेयरिंग चालू रखें", "साझा डिवाइस पर बैंकिंग पासवर्ड सेव करें"], 1, "Disconnecting and forgetting unused networks can prevent automatic connections to unsafe hotspots.", "डिस्कनेक्ट करके अनावश्यक नेटवर्क हटाने से असुरक्षित हॉटस्पॉट से अपने आप जुड़ना रोका जा सकता है।"),
    question("Medium", "A browser warning appears while you use public Wi-Fi to visit a website. What should you do?", "सार्वजनिक Wi-Fi पर वेबसाइट खोलते समय ब्राउज़र चेतावनी दिखाता है। क्या करें?", ["Ignore it because the network is public", "Stop and avoid entering information on the site", "Disable the warning", "Enter details using private browsing"], ["अनदेखा करें क्योंकि नेटवर्क सार्वजनिक है", "रुकें और वेबसाइट पर जानकारी न भरें", "चेतावनी बंद करें", "प्राइवेट ब्राउज़िंग में विवरण भरें"], 1, "Private browsing does not make an unsafe connection trustworthy. Do not bypass security warnings.", "प्राइवेट ब्राउज़िंग असुरक्षित कनेक्शन को विश्वसनीय नहीं बनाती। सुरक्षा चेतावनी पार न करें।"),
    question("Hard", "You must access a sensitive work resource while traveling. What should you use?", "यात्रा के दौरान संवेदनशील कार्य संसाधन खोलना जरूरी है। क्या उपयोग करें?", ["Any free hotspot", "Your organization's approved secure access method and trusted network", "A stranger's phone hotspot without asking", "A shared public computer"], ["कोई भी मुफ्त हॉटस्पॉट", "संस्था की स्वीकृत सुरक्षित पहुंच विधि और विश्वसनीय नेटवर्क", "बिना पूछे अजनबी का हॉटस्पॉट", "सार्वजनिक साझा कंप्यूटर"], 1, "Follow workplace security guidance and use approved protected access for sensitive resources.", "कार्यस्थल सुरक्षा निर्देश मानें और संवेदनशील संसाधनों के लिए स्वीकृत सुरक्षित पहुंच उपयोग करें।"),
    question("Medium", "A stranger offers a USB charging cable at an airport. What is safest?", "एयरपोर्ट पर अजनबी USB चार्जिंग केबल देता है। सबसे सुरक्षित क्या है?", ["Connect it to your unlocked phone", "Use your own charger and a power outlet or charge-only adapter", "Enable file transfer", "Share your unlock code"], ["अनलॉक फोन में लगाएं", "अपना चार्जर और बिजली सॉकेट या केवल चार्जिंग एडेप्टर उपयोग करें", "फाइल ट्रांसफर चालू करें", "अनलॉक कोड बताएं"], 1, "Use trusted charging equipment and avoid data connections from unknown accessories.", "विश्वसनीय चार्जिंग उपकरण उपयोग करें और अनजान एक्सेसरी के डेटा कनेक्शन से बचें।"),
    question("Easy", "What is a safer alternative to using an unknown hotspot for banking?", "बैंकिंग के लिए अनजान हॉटस्पॉट का सुरक्षित विकल्प क्या है?", ["Use the unknown hotspot with a short password", "Use mobile data or another trusted secure connection", "Use a public computer", "Ask a stranger to log in for you"], ["छोटे पासवर्ड वाला अनजान हॉटस्पॉट उपयोग करें", "मोबाइल डेटा या अन्य विश्वसनीय सुरक्षित कनेक्शन उपयोग करें", "सार्वजनिक कंप्यूटर लें", "अजनबी से लॉगिन करवाएं"], 1, "A trusted mobile connection is preferable for sensitive transactions when the hotspot cannot be verified.", "हॉटस्पॉट की पुष्टि न हो तो संवेदनशील लेनदेन के लिए विश्वसनीय मोबाइल कनेक्शन बेहतर है।"),
    question("Medium", "A site asks you to install a certificate or profile to use free Wi-Fi. What should you do?", "मुफ्त Wi-Fi उपयोग करने के लिए साइट प्रमाणपत्र या प्रोफाइल इंस्टॉल करने को कहती है। क्या करें?", ["Install it without checking", "Do not install unexpected profiles; confirm with the venue's official support", "Install it and enter all passwords", "Disable device protections"], ["बिना जांच इंस्टॉल करें", "अनपेक्षित प्रोफाइल इंस्टॉल न करें; स्थान की आधिकारिक सहायता से पुष्टि करें", "इंस्टॉल कर सभी पासवर्ड भरें", "डिवाइस सुरक्षा बंद करें"], 1, "Profiles and certificates can change device trust settings. Install only when verified and necessary.", "प्रोफाइल और प्रमाणपत्र डिवाइस की भरोसा सेटिंग बदल सकते हैं। केवल पुष्टि और जरूरत पर इंस्टॉल करें।"),
  ]),
  category("jobs", "Job Scams", "नौकरी धोखाधड़ी", [
    question("Easy", "A recruiter asks for a registration fee before an interview. What should you do?", "रिक्रूटर इंटरव्यू से पहले पंजीकरण शुल्क मांगता है। क्या करें?", ["Pay because the amount is small", "Verify the company through official sources and do not pay suspicious upfront fees", "Send bank credentials", "Ask for a discount"], ["राशि कम है इसलिए भुगतान करें", "आधिकारिक स्रोत से कंपनी जांचें और संदिग्ध अग्रिम फीस न दें", "बैंक प्रमाण भेजें", "छूट मांगें"], 1, "Upfront fees for a promised job are a warning sign. Verify the employer independently.", "नौकरी के वादे पर अग्रिम फीस चेतावनी संकेत है। नियोक्ता की स्वतंत्र जांच करें।"),
    question("Medium", "A work-from-home offer promises unusually high pay for simple tasks and asks for a deposit. What is safest?", "वर्क-फ्रॉम-होम ऑफर आसान काम के लिए बहुत अधिक वेतन और जमा राशि मांगता है। सुरक्षित तरीका क्या है?", ["Pay the deposit to reserve the role", "Research the employer and decline payment demands before employment", "Send your OTP", "Borrow money to pay quickly"], ["पद सुरक्षित करने के लिए जमा राशि दें", "नियोक्ता जांचें और नौकरी से पहले भुगतान मांगने से मना करें", "OTP भेजें", "जल्दी भुगतान के लिए उधार लें"], 1, "Unrealistic pay plus upfront deposits commonly indicate a fake job offer.", "अविश्वसनीय वेतन और अग्रिम जमा नकली नौकरी प्रस्ताव के आम संकेत हैं।"),
    question("Easy", "A recruiter contacts you only through a personal messaging account and will not name the employer. What should you do?", "रिक्रूटर केवल निजी मैसेजिंग खाते से संपर्क करता है और नियोक्ता का नाम नहीं बताता। क्या करें?", ["Send your resume and ID immediately", "Ask for verifiable company details and check them independently", "Pay a background-check fee", "Share your bank account password"], ["तुरंत रिज्यूमे और ID भेजें", "सत्यापित कंपनी विवरण मांगें और स्वयं जांचें", "बैकग्राउंड जांच फीस दें", "बैंक पासवर्ड साझा करें"], 1, "Confirm the employer, recruiter, and vacancy through official company channels before sharing sensitive data.", "संवेदनशील जानकारी देने से पहले आधिकारिक कंपनी माध्यम से नियोक्ता, रिक्रूटर और पद की पुष्टि करें।"),
    question("Medium", "A job application form asks for your bank PIN and OTP before an interview. What should you do?", "इंटरव्यू से पहले नौकरी आवेदन फॉर्म बैंक PIN और OTP मांगता है। क्या करें?", ["Fill them in to prove identity", "Do not provide them; report the request and verify the employer", "Send only the OTP", "Use a friend's banking details"], ["पहचान के लिए भरें", "न दें; अनुरोध रिपोर्ट करें और नियोक्ता की पुष्टि करें", "केवल OTP भेजें", "दोस्त के बैंक विवरण उपयोग करें"], 1, "Employers do not need your PIN or OTP. These credentials must remain private.", "नियोक्ता को आपका PIN या OTP नहीं चाहिए। ये प्रमाण गोपनीय रखें।"),
    question("Easy", "A recruiter says you must buy training materials from a specific link before getting hired. What should you do?", "रिक्रूटर नौकरी से पहले दिए लिंक से प्रशिक्षण सामग्री खरीदने को कहता है। क्या करें?", ["Buy it immediately", "Verify the role and requirement through the employer's official website", "Send payment by gift card", "Share your account password"], ["तुरंत खरीदें", "नियोक्ता की आधिकारिक वेबसाइट से पद और जरूरत जांचें", "गिफ्ट कार्ड से भुगतान करें", "खाते का पासवर्ड बताएं"], 1, "Fake recruiters may profit from required purchases. Verify the job and any costs independently.", "नकली रिक्रूटर अनिवार्य खरीद से लाभ कमा सकते हैं। नौकरी और खर्च की अलग से पुष्टि करें।"),
    question("Medium", "You receive an offer letter for a job you never interviewed for. What should you do?", "ऐसी नौकरी का ऑफर लेटर आता है जिसके लिए आपने इंटरव्यू नहीं दिया। क्या करें?", ["Accept and send documents", "Verify the vacancy and sender with the company using official contact details", "Pay a joining fee", "Post the letter with your personal details"], ["स्वीकार करके दस्तावेज भेजें", "आधिकारिक संपर्क से कंपनी में पद और भेजने वाले की पुष्टि करें", "जॉइनिंग फीस दें", "व्यक्तिगत जानकारी सहित पत्र पोस्ट करें"], 1, "Unexpected offers can be used to collect money or identity documents. Verify directly with the employer.", "अनपेक्षित ऑफर से पैसे या पहचान दस्तावेज जुटाए जा सकते हैं। नियोक्ता से सीधे पुष्टि करें।"),
    question("Hard", "A recruiter requests a scan of your identity documents over an unverified chat. What is safest?", "रिक्रूटर अपुष्ट चैट पर पहचान दस्तावेजों की स्कैन कॉपी मांगता है। सुरक्षित क्या है?", ["Send them to save the opportunity", "Verify the recruiter and share only necessary documents through an official secure process", "Send blank signed forms too", "Post them publicly for proof"], ["अवसर बचाने के लिए भेजें", "रिक्रूटर जांचें और आधिकारिक सुरक्षित प्रक्रिया से जरूरी दस्तावेज ही दें", "खाली हस्ताक्षरित फॉर्म भी भेजें", "प्रमाण के लिए सार्वजनिक पोस्ट करें"], 1, "Identity documents can be misused. Confirm legitimacy and minimize what you share.", "पहचान दस्तावेजों का दुरुपयोग हो सकता है। असलियत जांचें और साझा जानकारी सीमित रखें।"),
    question("Medium", "A company email domain differs slightly from the real company's domain. What should you do?", "कंपनी ईमेल डोमेन असली कंपनी के डोमेन से थोड़ा अलग है। क्या करें?", ["Assume it is a new HR system", "Check the official company site and contact HR using published details", "Reply with your Aadhaar number", "Open all attachments"], ["इसे नया HR सिस्टम मानें", "आधिकारिक कंपनी साइट जांचें और प्रकाशित विवरण से HR से संपर्क करें", "आधार नंबर से जवाब दें", "सभी अटैचमेंट खोलें"], 1, "Lookalike domains can impersonate employers. Verify the address before sending documents or money.", "मिलते-जुलते डोमेन नियोक्ता की नकल कर सकते हैं। दस्तावेज या पैसे भेजने से पहले पता जांचें।"),
    question("Easy", "A job offer asks you to deposit a cheque and return part of the money. What should you do?", "नौकरी का ऑफर चेक जमा करके कुछ पैसे वापस भेजने को कहता है। क्या करें?", ["Return the money after it appears", "Do not transfer funds; ask your bank and verify the employer", "Send the money to another applicant", "Share your online banking login"], ["राशि दिखने पर वापस भेजें", "पैसे न भेजें; बैंक से पूछें और नियोक्ता जांचें", "दूसरे आवेदक को भेजें", "ऑनलाइन बैंकिंग लॉगिन साझा करें"], 1, "Fake-check schemes can leave you responsible after a payment is reversed. Verify with your bank.", "नकली चेक योजना में भुगतान वापस होने पर नुकसान आपका हो सकता है। बैंक से पुष्टि करें।"),
    question("Medium", "A recruiter pressures you to decide immediately and pay a refundable placement fee. What should you do?", "रिक्रूटर तुरंत निर्णय लेने और वापस मिलने वाली प्लेसमेंट फीस देने का दबाव डालता है। क्या करें?", ["Pay before the offer expires", "Pause, verify the company, and avoid pressure-based payments", "Send your card PIN", "Borrow money from the recruiter"], ["ऑफर खत्म होने से पहले भुगतान करें", "रुकें, कंपनी जांचें और दबाव में भुगतान न करें", "कार्ड PIN भेजें", "रिक्रूटर से उधार लें"], 1, "Urgency and refundable-fee promises can be used to pressure job seekers into losing money.", "जल्दबाजी और वापस मिलने वाली फीस का वादा नौकरी चाहने वालों से पैसे लेने के लिए हो सकता है।"),
  ]),
  category("qr-scams", "QR Code Scams", "QR कोड धोखाधड़ी", [
    question("Easy", "A stranger says to scan a QR code to receive money, but your app asks for your UPI PIN. What should you do?", "अजनबी पैसे पाने के लिए QR स्कैन करने को कहता है, लेकिन ऐप UPI PIN मांगता है। क्या करें?", ["Enter the PIN", "Stop; receiving money does not require your UPI PIN", "Share the PIN with the sender", "Scan it again"], ["PIN डालें", "रुकें; पैसे पाने के लिए UPI PIN नहीं चाहिए", "भेजने वाले को PIN बताएं", "फिर स्कैन करें"], 1, "A PIN prompt usually authorizes a payment. Do not enter it to receive money.", "PIN मांगना आमतौर पर भुगतान अधिकृत करता है। पैसे पाने के लिए इसे न डालें।"),
    question("Medium", "You find a QR sticker pasted over a restaurant's payment code. What should you do?", "रेस्टोरेंट के भुगतान कोड के ऊपर QR स्टिकर चिपका दिखता है। क्या करें?", ["Scan it and pay", "Ask staff to verify the code and check the payee name before paying", "Pay without checking the recipient", "Share your UPI PIN with staff"], ["स्कैन करके भुगतान करें", "कर्मचारियों से कोड जांचें और भुगतान से पहले प्राप्तकर्ता नाम देखें", "प्राप्तकर्ता जांचे बिना भुगतान करें", "कर्मचारी को UPI PIN बताएं"], 1, "Tampered QR stickers can redirect payments. Verify the code and recipient with the business.", "बदले QR स्टिकर भुगतान दूसरी जगह भेज सकते हैं। व्यवसाय से कोड और प्राप्तकर्ता की पुष्टि करें।"),
    question("Easy", "What should you check after scanning a payment QR code but before confirming?", "भुगतान QR स्कैन करने के बाद पुष्टि से पहले क्या जांचें?", ["Only the QR design", "The recipient name and amount shown in your payment app", "Your phone wallpaper", "The number of nearby networks"], ["केवल QR डिजाइन", "भुगतान ऐप में प्राप्तकर्ता का नाम और राशि", "फोन वॉलपेपर", "आसपास नेटवर्कों की संख्या"], 1, "Confirm the payee and amount in your own app before authorizing a payment.", "भुगतान अधिकृत करने से पहले अपने ऐप में प्राप्तकर्ता और राशि जांचें।"),
    question("Medium", "A QR code on a poster promises a prize and opens a page asking for card details. What should you do?", "पोस्टर का QR इनाम का वादा कर कार्ड विवरण मांगने वाला पेज खोलता है। क्या करें?", ["Enter details to claim it", "Close it and verify the promotion through the organizer's official site", "Share your banking OTP", "Pay a claim fee"], ["इनाम पाने के लिए विवरण भरें", "बंद करें और आयोजक की आधिकारिक साइट पर प्रचार जांचें", "बैंकिंग OTP साझा करें", "दावा फीस दें"], 1, "QR codes can hide deceptive destinations. Verify promotions and never provide payment credentials to claim a surprise prize.", "QR कोड भ्रामक वेबसाइट छिपा सकते हैं। प्रचार की पुष्टि करें और अचानक इनाम के लिए भुगतान प्रमाण न दें।"),
    question("Easy", "A QR code directs you to install an unknown application. What is safest?", "QR कोड अनजान ऐप इंस्टॉल करने को कहता है। सुरक्षित तरीका क्या है?", ["Install it to continue", "Do not install; find the app through the official app store or provider", "Disable phone security", "Allow all permissions"], ["आगे बढ़ने के लिए इंस्टॉल करें", "इंस्टॉल न करें; आधिकारिक ऐप स्टोर या प्रदाता से ऐप खोजें", "फोन सुरक्षा बंद करें", "सभी अनुमतियां दें"], 1, "Use official app stores and verify the publisher; QR links can lead to malicious downloads.", "आधिकारिक ऐप स्टोर उपयोग करें और प्रकाशक जांचें; QR लिंक हानिकारक डाउनलोड पर ले जा सकते हैं।"),
    question("Medium", "A QR code opens a URL with a misspelled company name. What should you do?", "QR कोड ऐसा URL खोलता है जिसमें कंपनी का नाम गलत लिखा है। क्या करें?", ["Continue because the logo matches", "Close the page and navigate to the official website yourself", "Enter your login details", "Forward the URL"], ["लोगो सही है इसलिए आगे बढ़ें", "पेज बंद करें और आधिकारिक वेबसाइट स्वयं खोलें", "लॉगिन विवरण भरें", "URL आगे भेजें"], 1, "Check the destination domain before entering information; QR codes do not make a link trustworthy.", "जानकारी भरने से पहले गंतव्य डोमेन जांचें; QR कोड लिंक को विश्वसनीय नहीं बनाता।"),
    question("Hard", "You scanned a QR code and entered your account password on its page. What should you do?", "QR स्कैन करके खुले पेज पर आपने खाते का पासवर्ड दर्ज कर दिया। क्या करें?", ["Do nothing unless money disappears", "Change the password on the official service, secure reused accounts, and report it", "Tell the QR owner your new password", "Delete the QR scanner"], ["पैसे गायब होने तक कुछ न करें", "आधिकारिक सेवा पर पासवर्ड बदलें, दोहराए खाते सुरक्षित करें और रिपोर्ट करें", "QR मालिक को नया पासवर्ड बताएं", "QR स्कैनर मिटाएं"], 1, "Treat entered credentials as exposed and secure the affected accounts immediately.", "दर्ज प्रमाण उजागर मानें और प्रभावित खातों को तुरंत सुरक्षित करें।"),
    question("Easy", "Someone messages you a QR code to receive a refund. What is safest?", "कोई रिफंड पाने के लिए QR कोड भेजता है। सुरक्षित तरीका क्या है?", ["Scan and enter your PIN", "Verify the refund using the merchant's official app or support", "Share the code with everyone", "Pay a verification amount"], ["स्कैन करके PIN डालें", "व्यापारी के आधिकारिक ऐप या सहायता से रिफंड जांचें", "कोड सभी को भेजें", "सत्यापन राशि दें"], 1, "Verify refunds through official merchant channels and do not enter a PIN to receive money.", "आधिकारिक व्यापारी माध्यम से रिफंड जांचें और पैसे पाने के लिए PIN न डालें।"),
    question("Medium", "A QR code at a public place has no clear information about who placed it. What should you do?", "सार्वजनिक स्थान पर QR कोड लगाने वाले की स्पष्ट जानकारी नहीं है। क्या करें?", ["Scan it to find out", "Avoid scanning and use a verified source if you need the service", "Enter contact details after scanning", "Allow notifications"], ["जानने के लिए स्कैन करें", "स्कैन न करें; सेवा चाहिए तो सत्यापित स्रोत उपयोग करें", "स्कैन के बाद संपर्क विवरण भरें", "सूचनाएं अनुमति दें"], 1, "Unknown QR codes can lead to unsafe sites or payment requests. Use verified codes from the provider.", "अनजान QR असुरक्षित साइट या भुगतान अनुरोध खोल सकते हैं। प्रदाता के सत्यापित कोड उपयोग करें।"),
    question("Medium", "Your payment app shows a different recipient than the shop name after scanning. What should you do?", "QR स्कैन करने के बाद भुगतान ऐप दुकान के बजाय अलग प्राप्तकर्ता दिखाता है। क्या करें?", ["Pay and ask for a refund", "Cancel and confirm the correct payment details with the shop", "Enter the PIN to see more", "Send a second payment"], ["भुगतान करके रिफंड मांगें", "रद्द करें और दुकान से सही भुगतान विवरण पूछें", "और देखने के लिए PIN डालें", "दूसरा भुगतान करें"], 1, "Do not authorize a payment if the displayed recipient is unexpected. Verify before proceeding.", "दिखाया गया प्राप्तकर्ता अनपेक्षित हो तो भुगतान अधिकृत न करें। आगे बढ़ने से पहले पुष्टि करें।"),
  ]),
  category("social-media", "Social Media", "सोशल मीडिया", [
    question("Easy", "A new account using your friend's photo asks for emergency money. What should you do?", "मित्र की फोटो वाला नया खाता आपातकालीन पैसे मांगता है। क्या करें?", ["Send money immediately", "Verify with your friend through a different known channel", "Share your bank OTP", "Post your card details"], ["तुरंत पैसे भेजें", "दूसरे ज्ञात माध्यम से मित्र से पुष्टि करें", "बैंक OTP साझा करें", "कार्ड विवरण पोस्ट करें"], 1, "Impersonation accounts use stolen photos. Verify unusual money requests outside the account.", "नकली खाते चुराई फोटो उपयोग करते हैं। असामान्य पैसे के अनुरोध की दूसरे माध्यम से पुष्टि करें।"),
    question("Medium", "A social media quiz asks for your birthday, first school, and pet name. What should you consider?", "सोशल मीडिया क्विज़ जन्मदिन, पहले स्कूल और पालतू का नाम मांगता है। क्या ध्यान रखें?", ["These details are harmless", "They may reveal answers to account security questions; avoid sharing them publicly", "Share them only with followers", "Use them as your password"], ["ये विवरण हानिरहित हैं", "इनसे खाता सुरक्षा प्रश्नों के उत्तर पता चल सकते हैं; सार्वजनिक रूप से साझा न करें", "केवल फॉलोअर्स से साझा करें", "इन्हें पासवर्ड बनाएं"], 1, "Personal details can help attackers guess passwords or security answers.", "व्यक्तिगत विवरण से हमलावर पासवर्ड या सुरक्षा उत्तर का अनुमान लगा सकते हैं।"),
    question("Easy", "A direct message says your account will be suspended unless you log in through a link. What should you do?", "सीधा संदेश कहता है कि लिंक से लॉगिन न करने पर खाता बंद होगा। क्या करें?", ["Use the link", "Open the platform's official app or website and check account notifications", "Send your password to the sender", "Share the message publicly with your login"], ["लिंक उपयोग करें", "प्लेटफॉर्म का आधिकारिक ऐप या वेबसाइट खोलकर सूचनाएं जांचें", "भेजने वाले को पासवर्ड दें", "लॉगिन सहित संदेश सार्वजनिक करें"], 1, "Suspension threats are commonly used to steal credentials. Check your account through the official platform.", "खाता बंद करने की धमकी प्रमाण चुराने के लिए आम है। आधिकारिक प्लेटफॉर्म से खाता जांचें।"),
    question("Medium", "A social media app requests access to your contacts, microphone, and location for a simple wallpaper feature. What should you do?", "साधारण वॉलपेपर सुविधा वाला सोशल ऐप संपर्क, माइक्रोफोन और स्थान एक्सेस मांगता है। क्या करें?", ["Allow everything", "Review permissions and deny access that is not needed", "Share your password instead", "Disable the phone lock"], ["सभी अनुमतियां दें", "अनुमतियां जांचें और गैरजरूरी एक्सेस मना करें", "इसके बजाय पासवर्ड साझा करें", "फोन लॉक बंद करें"], 1, "Grant only permissions needed for the feature and review privacy settings regularly.", "सुविधा के लिए जरूरी अनुमतियां ही दें और गोपनीयता सेटिंग नियमित जांचें।"),
    question("Easy", "What is a good way to secure a social media account?", "सोशल मीडिया खाते को सुरक्षित करने का अच्छा तरीका क्या है?", ["Reuse your email password", "Use a unique password and enable multi-factor authentication", "Share login codes with followers", "Keep recovery details public"], ["ईमेल वाला पासवर्ड दोहराएं", "अलग पासवर्ड रखें और मल्टी-फैक्टर प्रमाणीकरण चालू करें", "फॉलोअर्स से लॉगिन कोड साझा करें", "रिकवरी विवरण सार्वजनिक रखें"], 1, "Unique credentials and MFA make unauthorized access more difficult.", "अलग प्रमाण और MFA अनधिकृत एक्सेस को कठिन बनाते हैं।"),
    question("Medium", "A post asks you to repost a link to claim free data and sign in with another service. What should you do?", "पोस्ट मुफ्त डेटा पाने के लिए लिंक शेयर करके दूसरी सेवा से लॉगिन करने को कहती है। क्या करें?", ["Repost and log in", "Verify the offer through the provider's official source before interacting", "Enter your password in the comments", "Share the link with family"], ["शेयर करके लॉगिन करें", "प्रतिक्रिया से पहले प्रदाता के आधिकारिक स्रोत से ऑफर जांचें", "टिप्पणियों में पासवर्ड दें", "लिंक परिवार को भेजें"], 1, "Promotional posts can be used for phishing or spreading scams. Confirm offers directly with the provider.", "प्रचार पोस्ट फ़िशिंग या धोखाधड़ी फैलाने के लिए हो सकती हैं। ऑफर की प्रदाता से पुष्टि करें।"),
    question("Hard", "You receive an MFA approval prompt that you did not request. What should you do?", "आपको ऐसा MFA स्वीकृति अनुरोध आता है जिसे आपने शुरू नहीं किया। क्या करें?", ["Approve it to stop notifications", "Deny it, change your password if needed, and review account activity", "Share the prompt with the requester", "Turn off MFA permanently"], ["सूचनाएं रोकने के लिए स्वीकार करें", "अस्वीकार करें, जरूरत हो तो पासवर्ड बदलें और खाता गतिविधि जांचें", "अनुरोधकर्ता को स्क्रीन भेजें", "MFA हमेशा के लिए बंद करें"], 1, "Unexpected prompts can indicate someone knows your password. Deny them and secure the account.", "अनपेक्षित अनुरोध से पता चल सकता है कि किसी को पासवर्ड पता है। अस्वीकार कर खाता सुरक्षित करें।"),
    question("Easy", "A stranger sends you a file claiming it contains photos of you. What should you do?", "अजनबी आपकी फोटो होने का दावा करके फाइल भेजता है। क्या करें?", ["Open it immediately", "Do not open it; verify the sender and report suspicious content", "Disable antivirus first", "Forward it to contacts"], ["तुरंत खोलें", "न खोलें; भेजने वाले की पुष्टि करें और संदिग्ध सामग्री रिपोर्ट करें", "पहले एंटीवायरस बंद करें", "संपर्कों को भेजें"], 1, "Unexpected files can contain malware or lead to credential theft. Avoid opening them.", "अनपेक्षित फाइल में मैलवेयर या प्रमाण चोरी का जोखिम हो सकता है। इन्हें खोलने से बचें।"),
    question("Medium", "You see a social media post spreading a sensational security warning with an unfamiliar link. What should you do?", "अपरिचित लिंक वाला सनसनीखेज सुरक्षा अलर्ट सोशल मीडिया पर दिखता है। क्या करें?", ["Share it immediately", "Check trusted official sources before sharing or clicking", "Enter your credentials to read it", "Send it to all groups"], ["तुरंत साझा करें", "शेयर या क्लिक करने से पहले विश्वसनीय आधिकारिक स्रोत जांचें", "पढ़ने के लिए प्रमाण दर्ज करें", "सभी समूहों में भेजें"], 1, "False urgent posts can spread scams and misinformation. Verify claims through trusted sources.", "झूठी तात्कालिक पोस्ट धोखाधड़ी और गलत सूचना फैला सकती हैं। विश्वसनीय स्रोत से पुष्टि करें।"),
    question("Easy", "What should you do if an unknown person asks for your live location on social media?", "सोशल मीडिया पर अनजान व्यक्ति लाइव लोकेशन मांगता है। क्या करें?", ["Share it to be friendly", "Do not share; limit location access and review who can see your posts", "Share your home address too", "Post it publicly for safety"], ["मित्रता के लिए साझा करें", "साझा न करें; लोकेशन एक्सेस सीमित करें और पोस्ट देखने वालों की जांच करें", "घर का पता भी दें", "सुरक्षा के लिए सार्वजनिक पोस्ट करें"], 1, "Location data can expose where you are or your routines. Share it only with trusted people when necessary.", "लोकेशन से आपकी जगह और दिनचर्या उजागर हो सकती है। जरूरत पर केवल विश्वसनीय लोगों से साझा करें।"),
  ]),
];

export default assessmentCategories;
